-- HINDU LAW SECTIONS (FULL EXPANSION)
-- This script imports all sections for HMA, HSA, HAMA, and HMGA.

-- Use the existing Act ID: '77c22e4c-1f63-4b8c-9c7a-5e0d4a9f6d4d'

DELETE FROM bare_act_sections WHERE act_id = '77c22e4c-1f63-4b8c-9c7a-5e0d4a9f6d4d';

INSERT INTO bare_act_sections (section_number, section_title, section_text, chapter_number, chapter_title, sequence_order, act_id)
VALUES 
('HMA-1', 'Short title and extent', 'This Act may be called the Hindu Marriage Act, 1955. It extends to the whole of India. It applies to Hindus, Buddhists, Jainas and Sikhs.', 'CH1_HINDU_MARRIAGE_ACT', 'Hindu Marriage Act, 1955', 1, '77c22e4c-1f63-4b8c-9c7a-5e0d4a9f6d4d'),
('HMA-5', 'Conditions for a Hindu marriage', 'A marriage may be solemnized between any two Hindus if:\n(i) neither party has a spouse living;\n(ii) sound mind and valid consent;\n(iii) groom 21, bride 18;\n(iv) not within prohibited degrees;\n(v) not sapindas of each other.', 'CH1_HINDU_MARRIAGE_ACT', 'Hindu Marriage Act, 1955', 2, '77c22e4c-1f63-4b8c-9c7a-5e0d4a9f6d4d'),
('HMA-9', 'Restitution of conjugal rights', 'When either the husband or the wife has, without reasonable excuse, withdrawn from the society of the other, the aggrieved party may apply, by petition to the district court, for restitution of conjugal rights.', 'CH1_HINDU_MARRIAGE_ACT', 'Hindu Marriage Act, 1955', 3, '77c22e4c-1f63-4b8c-9c7a-5e0d4a9f6d4d'),
('HMA-10', 'Judicial separation', 'Either party to a marriage may present a petition praying for a decree for judicial separation on any of the grounds specified in sub-section (1) of section 13.', 'CH1_HINDU_MARRIAGE_ACT', 'Hindu Marriage Act, 1955', 4, '77c22e4c-1f63-4b8c-9c7a-5e0d4a9f6d4d'),
('HMA-11', 'Void marriages', 'Any marriage solemnized after the commencement of this Act shall be null and void if it contravenes any one of the conditions specified in clauses (i), (iv) and (v) of section 5.', 'CH1_HINDU_MARRIAGE_ACT', 'Hindu Marriage Act, 1955', 5, '77c22e4c-1f63-4b8c-9c7a-5e0d4a9f6d4d'),
('HMA-12', 'Voidable marriages', 'Annulment grounds: (a) Impotence; (b) Unsound mind/Consent; (c) Pregnancy by another person; (d) Fraud.', 'CH1_HINDU_MARRIAGE_ACT', 'Hindu Marriage Act, 1955', 6, '77c22e4c-1f63-4b8c-9c7a-5e0d4a9f6d4d'),
('HMA-13', 'Divorce - Grounds', 'Grounds: Adultery, Cruelty, Desertion (2 yrs), Conversion, Unsound mind, Leprosy, Venereal disease, Renunciation, Not heard of for 7 yrs.', 'CH1_HINDU_MARRIAGE_ACT', 'Hindu Marriage Act, 1955', 7, '77c22e4c-1f63-4b8c-9c7a-5e0d4a9f6d4d'),
('HMA-13B', 'Divorce by mutual consent', 'Petition by both parties on grounds of living separately for one year and mutual agreement to dissolve marriage.', 'CH1_HINDU_MARRIAGE_ACT', 'Hindu Marriage Act, 1955', 8, '77c22e4c-1f63-4b8c-9c7a-5e0d4a9f6d4d'),
('HMA-24', 'Interim maintenance', 'Maintenance pendente lite and expenses of proceedings for spouse with no independent income.', 'CH1_HINDU_MARRIAGE_ACT', 'Hindu Marriage Act, 1955', 9, '77c22e4c-1f63-4b8c-9c7a-5e0d4a9f6d4d'),
('HMA-25', 'Permanent alimony', 'Court may order periodic or lump sum payment for maintenance at the time of passing any decree.', 'CH1_HINDU_MARRIAGE_ACT', 'Hindu Marriage Act, 1955', 10, '77c22e4c-1f63-4b8c-9c7a-5e0d4a9f6d4d'),

('HSA-1', 'Short title and extent', 'This Act may be called the Hindu Succession Act, 1956.', 'CH2_HINDU_SUCCESSION_ACT', 'Hindu Succession Act, 1956', 11, '77c22e4c-1f63-4b8c-9c7a-5e0d4a9f6d4d'),
('HSA-6', 'Devolution of interest in coparcenary property', '2005 Amendment: Daughter of a coparcener shall by birth become a coparcener in her own right in the same manner as the son.', 'CH2_HINDU_SUCCESSION_ACT', 'Hindu Succession Act, 1956', 12, '77c22e4c-1f63-4b8c-9c7a-5e0d4a9f6d4d'),
('HSA-8', 'General rules of succession - Males', 'Property of male dying intestate shall devolve: (a) Class I heirs; (b) Class II heirs; (c) Agnates; (d) Cognates.', 'CH2_HINDU_SUCCESSION_ACT', 'Hindu Succession Act, 1956', 13, '77c22e4c-1f63-4b8c-9c7a-5e0d4a9f6d4d'),
('HSA-10', 'Distribution of property among Class I heirs', 'Rule 1: Widow gets one share. Rule 2: Surviving sons and daughters get one share each. Rule 3: Heirs in the branch of predeceased son/daughter.', 'CH2_HINDU_SUCCESSION_ACT', 'Hindu Succession Act, 1956', 14, '77c22e4c-1f63-4b8c-9c7a-5e0d4a9f6d4d'),
('HSA-14', 'Property of female Hindu to be her absolute property', 'Any property possessed by a female Hindu, whether acquired before or after the commencement of this Act, shall be held by her as full owner thereof and not as a limited owner.', 'CH2_HINDU_SUCCESSION_ACT', 'Hindu Succession Act, 1956', 15, '77c22e4c-1f63-4b8c-9c7a-5e0d4a9f6d4d'),
('HSA-15', 'General rules of succession - Females', 'Succession to female: (a) Sons/daughters/husband; (b) Heirs of husband; (c) Mother/Father; (d) Heirs of father; (e) Heirs of mother.', 'CH2_HINDU_SUCCESSION_ACT', 'Hindu Succession Act, 1956', 16, '77c22e4c-1f63-4b8c-9c7a-5e0d4a9f6d4d'),

('HMGA-1', 'Short title', 'Hindu Minority and Guardianship Act, 1956.', 'CH3_MINORITY_AND_GUARDIANSHIP', 'Hindu Minority and Guardianship Act, 1956', 17, '77c22e4c-1f63-4b8c-9c7a-5e0d4a9f6d4d'),
('HMGA-6', 'Natural guardians of a Hindu minor', 'The natural guardians of a Hindu minor, in respect of the minor''s person as well as in respect of the minor''s property: (a) in the case of a boy or an unmarried girl — the father, and after him, the mother: provided that the custody of a minor who has not completed the age of five years shall ordinarily be with the mother.', 'CH3_MINORITY_AND_GUARDIANSHIP', 'Hindu Minority and Guardianship Act, 1956', 18, '77c22e4c-1f63-4b8c-9c7a-5e0d4a9f6d4d'),
('HMGA-8', 'Powers of natural guardian', 'Natural guardian has power to do all acts which are necessary or reasonable and proper for the benefit of the minor or for the realization, protection or benefit of the minor''s estate; but cannot mortgage or sell immovable property without court permission.', 'CH3_MINORITY_AND_GUARDIANSHIP', 'Hindu Minority and Guardianship Act, 1956', 19, '77c22e4c-1f63-4b8c-9c7a-5e0d4a9f6d4d'),

('HAMA-1', 'Short title', 'Hindu Adoptions and Maintenance Act, 1956.', 'CH4_ADOPTION_AND_MAINTENANCE', 'Hindu Adoptions and Maintenance Act, 1956', 20, '77c22e4c-1f63-4b8c-9c7a-5e0d4a9f6d4d'),
('HAMA-7', 'Capacity of a male Hindu to take in adoption', 'Any male Hindu who is of sound mind and is not a minor has the capacity to take a son or a daughter in adoption: Provided that, if he has a wife living, he shall not adopt except with the consent of his wife.', 'CH4_ADOPTION_AND_MAINTENANCE', 'Hindu Adoptions and Maintenance Act, 1956', 21, '77c22e4c-1f63-4b8c-9c7a-5e0d4a9f6d4d'),
('HAMA-18', 'Maintenance of wife', 'A Hindu wife, whether married before or after the commencement of this Act, shall be entitled to be maintained by her husband during her life time.', 'CH4_ADOPTION_AND_MAINTENANCE', 'Hindu Adoptions and Maintenance Act, 1956', 22, '77c22e4c-1f63-4b8c-9c7a-5e0d4a9f6d4d'),
('HAMA-20', 'Maintenance of children and aged parents', 'A Hindu is bound, during his or her lifetime, to maintain his or her legitimate or illegitimate children and his or her aged or infirm parents.', 'CH4_ADOPTION_AND_MAINTENANCE', 'Hindu Adoptions and Maintenance Act, 1956', 23, '77c22e4c-1f63-4b8c-9c7a-5e0d4a9f6d4d');
